"use client"

import * as React from "react"

import { Icon } from "@/components/ui/icon"
import { Item, ItemContent, ItemDescription, ItemGroup, ItemMedia, ItemTitle } from "@/components/ui/item"
import { Marker, MarkerContent } from "@/components/ui/marker"
import { Paper } from "@/components/ui/paper"
import { Tally } from "@/components/ui/tally"
import { FEED, WEEKS, type Entry, type Week } from "@/components/blocks/profile-page/components/profile-page-data"

function WeeklyTally({ weeks }: { weeks: Week[] }) {
  const titleId = React.useId()
  const best = Math.max(0, ...weeks.map((w) => w.pages))
  return (
    <Paper as="section" stock="slip" aria-labelledby={titleId} seed="weekly-tally" className="grid grid-rows-[auto_minmax(0,1fr)] gap-3 px-6 py-5">
      <div className="flex flex-wrap items-baseline justify-between gap-x-4">
        <h3 id={titleId} className="font-script text-3xl leading-none font-semibold">
          Pages, week by week
        </h3>
        <p className="text-sm text-muted-foreground">Best week: {best} pages</p>
      </div>
      <ol aria-label="Pages written each week" className="grid divide-y divide-rule-blue/60">
        {weeks.map((w, i) => {
          const now = i === weeks.length - 1
          return (
            <li key={w.label} className="grid min-h-9 grid-cols-[minmax(0,1fr)_3rem] items-center gap-x-3 gap-y-1 py-1.5 @md/profile:grid-cols-[8rem_minmax(0,1fr)_3rem] @md/profile:py-0">
              <span className="text-sm text-muted-foreground">{now ? "This week" : w.label}</span>
              <Tally
                count={w.pages}
                size="sm"
                tone={now ? "marker" : "ink"}
                label={`${w.pages} pages, ${w.label}`}
                seed={`week-${i}`}
                className="col-span-2 row-start-2 @md/profile:col-span-1 @md/profile:col-start-2 @md/profile:row-start-1"
              />
              <span className="ll-num col-start-2 row-start-1 text-end font-bold @md/profile:col-start-3">{w.pages}</span>
            </li>
          )
        })}
      </ol>
    </Paper>
  )
}

const DAYS: Entry["day"][] = ["Today", "Yesterday", "Last week"]

function Feed({ feed }: { feed: Entry[] }) {
  const titleId = React.useId()
  return (
    <Paper as="section" stock="paper" tilt={0.25} seed="profile-feed" aria-labelledby={titleId} className="grid content-start gap-2 px-6 py-5">
      <h3 id={titleId} className="font-script text-3xl leading-none font-semibold">
        Lately
      </h3>
      {DAYS.map((day) => (
        <div key={day} role="group" aria-label={day} className="grid">
          <Marker variant="separator">
            <MarkerContent>{day}</MarkerContent>
          </Marker>
          <ItemGroup>
            {feed.filter((e) => e.day === day).map((e) => (
              <Item key={e.id} size="sm">
                <ItemMedia variant="icon">
                  <Icon name={e.icon} />
                </ItemMedia>
                <ItemContent>
                  <ItemTitle>{e.title}</ItemTitle>
                  <ItemDescription>
                    {e.where} · <span className="ll-num">{e.time}</span>
                  </ItemDescription>
                </ItemContent>
              </Item>
            ))}
          </ItemGroup>
        </div>
      ))}
    </Paper>
  )
}

export function ProfilePageActivity({ weeks = WEEKS, feed = FEED }: { weeks?: Week[]; feed?: Entry[] }) {
  return (
    <div className="grid gap-10 @4xl/profile:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
      <WeeklyTally weeks={weeks} />
      <Feed feed={feed} />
    </div>
  )
}

import { Icon } from "@/components/ui/icon"
import { NotebookCover, NotebookCoverLabel } from "@/components/ui/notebook"
import { Sticker } from "@/components/ui/sticker"
import { BADGES, SHELF, type Badge, type ShelfNotebook } from "@/components/blocks/profile-page/components/profile-page-data"
import { cn } from "@/lib/utils"

export function ProfilePageNotebooks({ shelf = SHELF }: { shelf?: ShelfNotebook[] }) {
  return (
    <ul aria-label="Notebooks" className="flex flex-wrap justify-center gap-x-8 gap-y-10 @md/profile:justify-start">
      {shelf.map((n) => (
        <li key={n.name} className="grid justify-items-center gap-3">
          <NotebookCover tone={n.tone} band={n.name !== "Letters"} seed={n.name} role="group" aria-label={`${n.name} notebook`}>
            <NotebookCoverLabel>{n.name}</NotebookCoverLabel>
          </NotebookCover>
          <span className="ll-num text-sm text-muted-foreground">{n.pages} pages</span>
        </li>
      ))}
    </ul>
  )
}

export function ProfilePageStickers({ badges = BADGES }: { badges?: Badge[] }) {
  const earned = badges.filter((b) => b.earned).length
  return (
    <div className="grid gap-4">
      <p className="text-muted-foreground">
        <b className="ll-num text-foreground">{earned}</b> of {badges.length} stickers earned.
      </p>
      <ul aria-label="Stickers" className="grid grid-cols-2 gap-x-6 gap-y-8 @lg/profile:grid-cols-3 @3xl/profile:grid-cols-4">
        {badges.map((b) => (
          <li key={b.id} className="grid justify-items-center gap-2 text-center">
            <Sticker name={b.sticker} size={88} seed={b.id} shadow={!!b.earned} className={cn(!b.earned && "opacity-35 grayscale")} />
            <p className="font-bold">{b.name}</p>
            <p className="flex items-center gap-1 text-sm text-muted-foreground">
              {b.earned ? (
                <>
                  <Icon name="check" size={14} />
                  Earned {b.earned}
                </>
              ) : (
                <>
                  <Icon name="lock" size={14} />
                  {b.how}
                </>
              )}
            </p>
          </li>
        ))}
      </ul>
    </div>
  )
}
